class Solution:
    def ambiguousCoordinates(self, s: str) -> List[str]:
        def representations(digits: str) -> List[str]:
            result = []

            if len(digits) == 1 or digits[0] != "0":
                result.append(digits)

            for i in range(1, len(digits)):
                integer, fraction = digits[:i], digits[i:]
                if (len(integer) == 1 or integer[0] != "0") and fraction[-1] != "0":
                    result.append(integer + "." + fraction)

            return result

        digits = s[1:-1]
        answer = []

        for i in range(1, len(digits)):
            left_values = representations(digits[:i])
            right_values = representations(digits[i:])

            for left in left_values:
                for right in right_values:
                    answer.append(f"({left}, {right})")

        return answer
