from typing import List


class Solution:
    def hitBricks(self, grid: List[List[int]], hits: List[List[int]]) -> List[int]:
        rows, cols = len(grid), len(grid[0])
        roof = rows * cols
        parent = list(range(roof + 1))
        size = [1] * (roof + 1)

        def find(x: int) -> int:
            while x != parent[x]:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            root_a, root_b = find(a), find(b)
            if root_a == root_b:
                return
            if size[root_a] < size[root_b]:
                root_a, root_b = root_b, root_a
            parent[root_b] = root_a
            size[root_a] += size[root_b]

        removed = [False] * len(hits)
        for i, (r, c) in enumerate(hits):
            if grid[r][c] == 1:
                removed[i] = True
                grid[r][c] = 0

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 0:
                    continue

                index = r * cols + c
                if r == 0:
                    union(index, roof)
                if r > 0 and grid[r - 1][c] == 1:
                    union(index, (r - 1) * cols + c)
                if c > 0 and grid[r][c - 1] == 1:
                    union(index, r * cols + c - 1)

        result = [0] * len(hits)
        directions = ((1, 0), (-1, 0), (0, 1), (0, -1))

        for i in range(len(hits) - 1, -1, -1):
            if not removed[i]:
                continue

            r, c = hits[i]
            before = size[find(roof)]
            grid[r][c] = 1
            index = r * cols + c

            if r == 0:
                union(index, roof)

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                    union(index, nr * cols + nc)

            after = size[find(roof)]
            result[i] = max(0, after - before - 1)

        return result
