from typing import List

class Solution:
    def numFactoredBinaryTrees(self, arr: List[int]) -> int:
        MOD = 10**9 + 7
        arr.sort()
        index = {value: i for i, value in enumerate(arr)}
        dp = [1] * len(arr)

        for i, root in enumerate(arr):
            for j in range(i):
                left = arr[j]
                if root % left == 0:
                    right = root // left
                    if right in index:
                        dp[i] = (dp[i] + dp[j] * dp[index[right]]) % MOD

        return sum(dp) % MOD
```

