class Solution:
    def canCross(self, stones: List[int]) -> bool:
        reachable = {stone: set() for stone in stones}
        reachable[0].add(0)
        last_stone = stones[-1]

        for stone in stones:
            for previous_jump in reachable[stone]:
                for jump in (
                    previous_jump - 1,
                    previous_jump,
                    previous_jump + 1,
                ):
                    if jump <= 0:
                        continue

                    next_stone = stone + jump
                    if next_stone == last_stone:
                        return True

                    if next_stone in reachable:
                        reachable[next_stone].add(jump)

        return False
