from typing import List
from math import gcd
from functools import lru_cache

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        m = len(nums)
        full_mask = (1 << m) - 1

        pair_gcd = [[0] * m for _ in range(m)]
        for i in range(m):
            for j in range(i + 1, m):
                pair_gcd[i][j] = gcd(nums[i], nums[j])

        @lru_cache(None)
        def dp(mask: int) -> int:
            if mask == full_mask:
                return 0

            operation = mask.bit_count() // 2 + 1
            best = 0

            for i in range(m):
                if mask & (1 << i):
                    continue
                for j in range(i + 1, m):
                    if mask & (1 << j):
                        continue
                    next_mask = mask | (1 << i) | (1 << j)
                    score = operation * pair_gcd[i][j] + dp(next_mask)
                    best = max(best, score)

            return best

        return dp(0)
```

