from functools import lru_cache

class Solution:
    def maximumANDSum(self, nums: List[int], numSlots: int) -> int:
        powers = [3 ** i for i in range(numSlots)]

        @lru_cache(None)
        def dp(index: int, state: int) -> int:
            if index == len(nums):
                return 0

            best = 0
            for slot in range(numSlots):
                if (state // powers[slot]) % 3 < 2:
                    best = max(
                        best,
                        (nums[index] & (slot + 1))
                        + dp(index + 1, state + powers[slot])
                    )
            return best

        return dp(0, 0)
