from collections import deque

class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        n = len(graph)
        reverse_graph = [[] for _ in range(n)]
        outdegree = [0] * n

        for node, neighbors in enumerate(graph):
            outdegree[node] = len(neighbors)
            for neighbor in neighbors:
                reverse_graph[neighbor].append(node)

        queue = deque(node for node in range(n) if outdegree[node] == 0)
        safe = [False] * n

        while queue:
            node = queue.popleft()
            safe[node] = True

            for predecessor in reverse_graph[node]:
                outdegree[predecessor] -= 1
                if outdegree[predecessor] == 0:
                    queue.append(predecessor)

        return [node for node in range(n) if safe[node]]
