from typing import List

class Solution:
    def minMalwareSpread(self, graph: List[List[int]], initial: List[int]) -> int:
        n = len(graph)
        infected = set(initial)
        visited = [False] * n
        saved = {node: 0 for node in initial}

        for start in range(n):
            if start in infected or visited[start]:
                continue

            stack = [start]
            visited[start] = True
            size = 0
            adjacent_infected = set()

            while stack:
                node = stack.pop()
                size += 1

                for neighbor in range(n):
                    if not graph[node][neighbor]:
                        continue
                    if neighbor in infected:
                        adjacent_infected.add(neighbor)
                    elif not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)

            if len(adjacent_infected) == 1:
                source = next(iter(adjacent_infected))
                saved[source] += size

        return min(initial, key=lambda node: (-saved[node], node))
