            return -1

        def can_make(day: int) -> bool:
            bouquets = 0
            adjacent = 0

            for bloom in bloomDay:
                if bloom <= day:
                    adjacent += 1
                    if adjacent == k:
                        bouquets += 1
                        adjacent = 0
                        if bouquets >= m:
