class Solution:
    def splitArray(self, nums: List[int], k: int) -> int:
        left, right = max(nums), sum(nums)

        while left < right:
            limit = (left + right) // 2
            subarrays = 1
            current_sum = 0

            for num in nums:
                if current_sum + num > limit:
                    subarrays += 1
                    current_sum = num
                else:
                    current_sum += num

            if subarrays <= k:
                right = limit
            else:
                left = limit + 1

