class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        i = j = 0
        star = -1
        matched = 0

        while i < len(s):
            if j < len(p) and (p[j] == "?" or p[j] == s[i]):
                i += 1
                j += 1
            elif j < len(p) and p[j] == "*":
                star = j
                matched = i
                j += 1
            elif star != -1:
                matched += 1
                i = matched
                j = star + 1
            else:
                return False

        while j < len(p) and p[j] == "*":
            j += 1

        return j == len(p)
